<?php
declare(strict_types=1);
namespace App\Interface\Http\Study\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Study\DTO\Request\CreateDirectedStudyPlanRequestDto;use App\Application\Study\Service\CreateDirectedStudyPlanService;use App\Application\Study\Service\ListDirectedStudyPlansService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class DirectedStudyPlanController { public function __construct(private readonly AuthService $auth,private readonly CreateDirectedStudyPlanService $create,private readonly ListDirectedStudyPlansService $list,private readonly ApiResponseFactory $responses){} public function list(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a):ResponseInterface{try{$u=$this->auth->currentUser($a);return $this->responses->success($s,$this->list->list($u->id),(string)$r->getAttribute('request_id'));}catch(\DomainException|UnavailableUserException){return $this->responses->problem($s,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}} public function create(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a,string $name,string $exam,string $position):ResponseInterface{try{$u=$this->auth->currentUser($a);return $this->responses->success($s,$this->create->create(new CreateDirectedStudyPlanRequestDto($u->id,$exam,$position,$name)),(string)$r->getAttribute('request_id'),201);}catch(\InvalidArgumentException){return $this->responses->problem($s,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$r->getAttribute('request_id'));}catch(\DomainException|UnavailableUserException){return $this->responses->problem($s,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}} }
